import { readFileSync } from "node:fs";
import { join } from "node:path";
import ts from "typescript";
import { decodeExecuteAction } from "../../src/protocol/codec.ts";
import type { ExecuteAction } from "../../src/protocol/types.ts";

// Generated by the actual Product SQL-sandbox scheduling tests, not a hand-built
// Worker input. Missing generation is an error, never a silently skipped proof.
export function productPreprobeWire(name: string): Record<string, unknown> {
  const directory = process.env.QE_PREPROBE_WIRE_DIR;
  if (!directory)
    throw new Error("Generate isolated Product preprobe wire fixtures first.");
  const wire = JSON.parse(
    readFileSync(join(directory, `${name}.json`), "utf8"),
  );
  return wire;
}

export function productPreprobeAction(name: string): ExecuteAction {
  const wire = productPreprobeWire(name);
  return decodeExecuteAction(wire, String(wire.worker_id));
}

// Execute only these two memory-only production AST bodies. Do not construct a
// Worker (which owns real infrastructure). This also prevents a test-local copy
// of receipt-producing conditions from drifting away from Worker serialization.
const source = ts.createSourceFile(
  "worker.ts",
  readFileSync(new URL("../../src/worker.ts", import.meta.url), "utf8"),
  ts.ScriptTarget.Latest,
  true,
);
let producer = "",
  reader = "";
function visit(node: ts.Node) {
  if (
    ts.isIfStatement(node) &&
    node.expression.getText(source).includes("acceptance.created") &&
    node.thenStatement
      .getText(source)
      .includes("this.freshDiagnosticActions.set(")
  )
    producer = node.getText(source);
  if (
    ts.isNewExpression(node) &&
    node.expression.getText(source) === "ClaudeCodeHarness"
  ) {
    const claim = node.arguments?.[7];
    if (claim && ts.isArrowFunction(claim)) reader = claim.body.getText(source);
  }
  ts.forEachChild(node, visit);
}
visit(source);
if (!producer || !reader)
  throw new Error("Missing reviewed memory-only receipt bodies.");

export function productAcceptanceReceipt(
  action: ExecuteAction,
  created: boolean,
  current = true,
  serverGeneration = 9,
) {
  const owner = {
    freshDiagnosticActions: new Map<string, string>(),
    readyGeneration: 1,
    channel: {
      isCurrentGeneration: () => current,
      currentServerGeneration: () => serverGeneration,
    },
  };
  new Function("acceptance", "action", "generation", producer).call(
    owner,
    { created },
    action,
    1,
  );
  const claim = new Function("actionId", reader);
  return {
    claim: (id = action.action_id): string | null => claim.call(owner, id),
    pending: () => owner.freshDiagnosticActions.size,
  };
}
